B=[
('الْقُدْسُ','Kudüs',[
('ثُمَّ سَارَ صَلَاحُ الدِّينِ إِلَى الْقُدْسِ، وَكَانَ الصَّلِيبِيُّونَ قَدْ أَخَذُوهَا قَبْلَ تِسْعِينَ سَنَةً.','Sonra Selâhaddin Kudüs’e yürüdü; Haçlılar onu doksan yıl önce almışlardı.'),
('وَكَانُوا يَوْمَئِذٍ قَدْ قَتَلُوا أَهْلَهَا حَتَّى جَرَتِ الدِّمَاءُ فِي الشَّوَارِعِ.','O gün halkını öldürmüşler, öyle ki sokaklarda kan akmıştı.'),
('فَحَاصَرَ الْمَدِينَةَ أَيَّامًا، ثُمَّ طَلَبَ أَهْلُهَا الْأَمَانَ.','Şehri günlerce kuşattı, sonra halkı aman diledi.'),
('فَقَالَ لَهُ بَعْضُ أُمَرَائِهِ: «افْعَلْ بِهِمْ مَا فَعَلُوا بِنَا.»','Bazı emirleri ona dedi ki: “Onlara bize yaptıklarını yap.”'),
('فَقَالَ صَلَاحُ الدِّينِ: «لَا، بَلْ نَفْعَلُ مَا يَأْمُرُنَا بِهِ دِينُنَا.»','Selâhaddin dedi ki: “Hayır, biz dinimizin emrettiğini yaparız.”'),
('فَأَعْطَاهُمُ الْأَمَانَ، وَدَخَلَ الْمَدِينَةَ فِي السَّابِعِ وَالْعِشْرِينَ مِنْ رَجَبٍ، لَيْلَةَ الْإِسْرَاءِ.','Onlara aman verdi ve şehre 27 Recep’te, İsrâ gecesinde girdi.'),
('فَلَمْ يُقْتَلْ أَحَدٌ، وَلَمْ تُنْهَبْ دَارٌ.','Kimse öldürülmedi, hiçbir ev yağmalanmadı.')]),
('الرَّحْمَةُ','Merhamet',[
('وَخَرَجَ النَّصَارَى مِنَ الْمَدِينَةِ، وَكَانَ عَلَى كُلِّ وَاحِدٍ فِدْيَةٌ صَغِيرَةٌ.','Hıristiyanlar şehirden çıktılar; her birinin üzerinde küçük bir fidye vardı.'),
('فَجَاءَتْ نِسَاءٌ يَبْكِينَ، وَقُلْنَ: «أَزْوَاجُنَا أَسْرَى، وَلَيْسَ مَعَنَا مَالٌ.»','Ağlayan kadınlar geldi ve dediler ki: “Kocalarımız esir ve yanımızda para yok.”'),
('فَرَقَّ لَهُنَّ صَلَاحُ الدِّينِ، وَأَطْلَقَ أَزْوَاجَهُنَّ، وَأَعْطَاهُنَّ مِنْ مَالِهِ.','Selâhaddin onlara acıdı, kocalarını serbest bıraktı ve onlara kendi malından verdi.'),
('وَأَطْلَقَ أَخُوهُ الْعَادِلُ أَلْفًا مِنَ الْفُقَرَاءِ بِغَيْرِ فِدْيَةٍ.','Kardeşi el-Âdil de fakirlerden bini fidyesiz serbest bıraktı.'),
('وَتَعَجَّبَ النَّصَارَى مِنْ هَذَا الْعَدْلِ، وَتَحَدَّثُوا بِهِ فِي بِلَادِهِمْ.','Hıristiyanlar bu adalete şaştılar ve kendi ülkelerinde bundan söz ettiler.'),
('فَصَارَ اسْمُ صَلَاحِ الدِّينِ مَعْرُوفًا فِي الشَّرْقِ وَالْغَرْبِ بِالْكَرَمِ وَالشَّرَفِ.','Selâhaddin’in adı doğuda ve batıda cömertlik ve şerefle bilinir oldu.')]),
('رِيتْشَارْدُ قَلْبُ الْأَسَدِ','Aslan Yürekli Richard',[
('فَغَضِبَ مُلُوكُ أُورُبَّا، وَجَاءَتْ حَمْلَةٌ جَدِيدَةٌ بِقِيَادَةِ رِيتْشَارْدَ مَلِكِ الْإِنْجِلِيزِ.','Avrupa kralları öfkelendi ve İngiliz kralı Richard komutasında yeni bir sefer geldi.'),
('وَدَامَتِ الْحَرْبُ سِنِينَ، وَكَانَ كُلٌّ مِنَ الْمَلِكَيْنِ يَحْتَرِمُ الْآخَرَ.','Savaş yıllarca sürdü; iki kraldan her biri diğerine saygı duyuyordu.'),
('وَمَرِضَ رِيتْشَارْدُ مَرَّةً، فَأَرْسَلَ إِلَيْهِ صَلَاحُ الدِّينِ الْفَاكِهَةَ وَالثَّلْجَ مِنَ الْجِبَالِ.','Bir keresinde Richard hastalandı; Selâhaddin ona dağlardan meyve ve kar gönderdi.'),
('وَقُتِلَ فَرَسُ رِيتْشَارْدَ فِي الْمَعْرَكَةِ، فَأَرْسَلَ إِلَيْهِ فَرَسَيْنِ.','Richard’ın atı savaşta öldürüldü; Selâhaddin ona iki at gönderdi.'),
('وَقَالَ: «لَا يَلِيقُ بِمَلِكٍ أَنْ يُقَاتِلَ مَاشِيًا.»','Dedi ki: “Bir krala yaya savaşmak yakışmaz.”'),
('ثُمَّ تَصَالَحَا، وَبَقِيَتِ الْقُدْسُ بِيَدِ الْمُسْلِمِينَ، وَسُمِحَ لِلنَّصَارَى بِزِيَارَتِهَا.','Sonra barıştılar; Kudüs Müslümanların elinde kaldı ve Hıristiyanların onu ziyaret etmesine izin verildi.')]),
('وَفَاةُ السُّلْطَانِ','Sultanın vefatı',[
('رَجَعَ صَلَاحُ الدِّينِ إِلَى دِمَشْقَ مُتْعَبًا بَعْدَ سِنِينَ طَوِيلَةٍ مِنَ الْجِهَادِ.','Selâhaddin uzun cihat yıllarından sonra yorgun olarak Dımaşk’a döndü.'),
('وَفِي سَنَةِ خَمْسِمِائَةٍ وَتِسْعٍ وَثَمَانِينَ مَرِضَ، وَتُوُفِّيَ وَهُوَ فِي الْخَامِسَةِ وَالْخَمْسِينَ.','589 yılında hastalandı ve elli beş yaşındayken vefat etti.'),
('فَفَتَحُوا خِزَانَتَهُ، فَلَمْ يَجِدُوا فِيهَا إِلَّا دِينَارًا وَاحِدًا وَأَرْبَعِينَ دِرْهَمًا.','Hazinesini açtılar ve içinde bir dinar ile kırk dirhemden başka bir şey bulamadılar.'),
('لَمْ يَتْرُكْ دَارًا وَلَا بُسْتَانًا وَلَا قَرْيَةً.','Ne bir ev ne bir bahçe ne de bir köy bıraktı.'),
('فَقَدْ أَنْفَقَ مَالَهُ كُلَّهُ عَلَى النَّاسِ وَالْجُيُوشِ وَالْمَدَارِسِ.','Bütün malını insanlara, ordulara ve medreselere harcamıştı.'),
('وَبَكَاهُ النَّاسُ فِي كُلِّ مَكَانٍ، حَتَّى أَعْدَاؤُهُ.','İnsanlar her yerde ona ağladı, düşmanları bile.'),
('وَهَكَذَا يَكُونُ الْمُلْكُ إِذَا اقْتَرَنَ بِالْعَدْلِ وَالرَّحْمَةِ.','İşte hükümranlık adalet ve merhametle birleşince böyle olur.')]),
]
